package com.elektoryk.scan.model;
import org.json.*;import java.util.UUID;
public class WorkerShift {public String id=UUID.randomUUID().toString();public String workerName="Підсобник";public double hourlyRate=0;public long startedAt=0,endedAt=0;public String note="";public boolean isOpen(){return startedAt>0&&endedAt==0;}public double hours(long now){if(startedAt<=0)return 0;long e=endedAt>0?endedAt:now;return Math.max(0,(e-startedAt)/3600000.0);}public double pay(long now){return hours(now)*hourlyRate;}public JSONObject toJson()throws JSONException{JSONObject o=new JSONObject();o.put("id",id);o.put("workerName",workerName);o.put("hourlyRate",hourlyRate);o.put("startedAt",startedAt);o.put("endedAt",endedAt);o.put("note",note);return o;}public static WorkerShift fromJson(JSONObject o){if(o==null)return null;WorkerShift x=new WorkerShift();x.id=o.optString("id",x.id);x.workerName=o.optString("workerName","Підсобник");x.hourlyRate=o.optDouble("hourlyRate",0);x.startedAt=o.optLong("startedAt",0);x.endedAt=o.optLong("endedAt",0);x.note=o.optString("note","");return x;}}
